def point(
    age,
    number,
    title,
    date_range,
    assignments,
    note="",
    summary="",
    *,
    suffix="",
    point_type="sequential",
    boundary_rationale="",
    assignment_details=None,
    filename_slug=None,
    as_of=None,
    review_due=None,
):
    details = assignment_details or {}
    return {
        "age": age,
        "number": number,
        "suffix": suffix,
        "title": title,
        "date_range": date_range,
        "assignments": dict(zip(HOUSES, assignments, strict=True)),
        "note": note,
        "summary": summary,
        "point_type": point_type,
        "boundary_rationale": boundary_rationale or "The supplied Atlas boundary is retained as a representative historical coordinate; exact internal phases remain Working.",
        "assignment_details": {
            house: {
                "temporal_fit": details.get(house, {}).get("temporal_fit", "Working representative"),
                "relevance_range": details.get(house, {}).get("relevance_range", date_range),
                "note": details.get(house, {}).get("note", "Exact internal overlap and phase boundaries remain Working."),
            }
            for house in HOUSES
        },
        "filename_slug": filename_slug,
        "as_of": as_of,
        "review_due": review_due,
    }


