def slugify(value: str) -> str:
    replacements = {"ü": "u", "Ü": "u", "Š": "s", "š": "s", "’": "", "ō": "o"}
    for old, new in replacements.items():
        value = value.replace(old, new)
    value = value.lower()
    value = re.sub(r"[^a-z0-9]+", "_", value)
    return value.strip("_")


