def initialize_completion_review() -> None:
    """Install the reviewed Ages IV–VI records from one maintainable source."""
    for p in POINTS:
        coordinate = (p["age"], p["number"])
        if coordinate not in COMPLETION_POINT_SOURCES:
            continue
        dossier_batch = {}
        sources = list(COMPLETION_POINT_SOURCES[coordinate])
        for house in HOUSES:
            culture = p["assignments"][house]
            status = "Reviewed completion dossier; assignment remains Working"
            if culture == "Nazi Germany":
                status = "Reviewed cautionary dossier; only atrocity documentation, totalitarian warning, and institutional refusal are inherited; assignment remains Working"
            elif coordinate == (6, 5):
                status = "Reviewed open dossier as of 2026-08-12; recurring review required; assignment remains Working"
            dossier_batch[house] = {
                "culture": culture,
                "file": f"{slugify(culture).upper()}.md",
                "status": status,
                "figures": "Representative figures and officeholders remain source-specific; no individual is made the timeless representative of this culture or Point.",
                "locations": "The assignment is bounded to documented sites and networks within the Point range; capitals and famous centers do not stand for every region or community.",
                "records": "The linked institutional and scholarly sources provide the completion bibliography; primary records, objects, statistics, and later interpretation must retain separate provenance.",
                "government": "Institutions varied by phase, place, jurisdiction, status, and community; state or court records are not treated as proof of uniform implementation.",
                "worldview": "Religious, philosophical, political, and social worldviews remain plural and contested; none transfers as Hollow Grove doctrine.",
                "knowledge": f"The reviewed knowledge inheritance is limited to the named {house} Gifts and their dated evidence, with authorship, exclusion, and uncertainty retained.",
                "technology": "Tools and infrastructure are recorded with labor, supply, maintenance, environmental, military, and civilian consequences rather than as context-free progress.",
                "art": "Objects, texts, performance, and design remain attributed to makers, patrons, workshops, audiences, custody, and later collection history; replica style is excluded.",
                "warfare": "War, conquest, coercion, colonization, genocide, forced labor, surveillance, and displacement are evidence and cautions, never proof of Capacity or transferable Gifts.",
                "trade": "Exchange is described through dated routes, commodities, intermediaries, labor, unequal power, interruption, and local reception rather than anonymous connectivity.",
                "relationships": "Point co-placement creates a comparison, not proof of direct contact, shared identity, equal power, or a single historical system.",
            }

            gifts = gifts_for_assignment(p, house)
            key = f"age_{p['age']:02d}_point_{p['number']:02d}_{slugify(culture)}_evidence_interface"
            name = f"{culture} Evidence and Translation Interface"
            refs = [(p["age"], p["number"])]
            MANIFESTATIONS[house].append((
                key,
                name,
                list(gifts),
                [culture] * len(gifts),
                "interface",
                f"A source-bounded {house} interface translates the {culture} assignment without importing historical sovereignty, coercion, hierarchy, or costume.",
                "existing House archive, library, curriculum, maintenance, or public-interpretation program",
                f"existing {house} evidence-literacy and cultural-memory program",
                "provenance and evidence-boundary steward",
                "source date, claim scope, uncertainty, custody, affected communities, refusal, and revision references",
                refs,
            ))
            mid = f"manifestation.{HOUSE_SLUGS[house]}.{key}"
            open_note = " Time-sensitive claims are current only through 2026-08-12 and must be re-reviewed." if p["age"] == 6 else ""
            caution = " For Nazi Germany, the interface contains only evidence of atrocity and institutional failure, never a transferable aesthetic or operational model." if culture == "Nazi Germany" else ""
            REVIEWED_MANIFESTATIONS[mid] = {
                "purpose": f"Make the {culture} assignment's dates, sources, inherited Gifts, exclusions, and later revisions inspectable.",
                "ancestry": f"The reviewed {p['title']} evidence window ({p['date_range']}) and its bounded {culture} assignment; Gifts are analytical categories, not proof of cultural uniformity.",
                "interpretation": f"{house} receives documented practices and cautions through existing House authority; historical rule, rank, violence, extraction, and identity claims do not transfer.{caution}",
                "appearance": "A contemporary universal dark-blue evidence interface using the locked House palette, source cards, dated layers, uncertainty marks, revision history, and accessible text; no replica monument, uniform, flag, or sacred object.",
                "institutional_role": f"A read-only provenance, library, curriculum, and cultural-memory service inside existing {house} authority; it creates no office, jurisdiction, confirmation, Clearance, or Capacity.",
                "gameplay": "Inspect source scope, compare phases, trace Gift provenance, surface exclusions and civilian effects, and propose a separately reviewable interpretation.",
                "implementation": "Store source date, publisher, claim scope, confidence, affected communities, exclusions, custody, and revision date. Keep evidence, scholarly interpretation, and Hollow Grove adaptation as separate fields.",
                "confidence": f"Completion-level review: high confidence in the Point boundary and institutional source bundle; culture-specific detail remains revision-capable.{open_note}",
                "sources": sources,
            }
        REVIEWED_DOSSIERS[coordinate] = dossier_batch


initialize_completion_review()


def age_for(number: int) -> dict:
    return next(age for age in AGES if age["number"] == number)


def split_point_number(point_number: int | str) -> tuple[int, str]:
    match = re.fullmatch(r"([0-9]+)([A-Za-z]?)", str(point_number))
    if not match:
        raise ValueError(f"Invalid Point coordinate: {point_number}")
    return int(match.group(1)), match.group(2).upper()


def point_for(age_number: int, point_number: int | str) -> dict:
    number, suffix = split_point_number(point_number)
    matches = [
        p for p in POINTS
        if p["age"] == age_number and p["number"] == number
        and (not suffix or p["suffix"] == suffix)
    ]
    if not matches:
        raise StopIteration(f"No Point at Age {age_number}, coordinate {point_number}")
    return matches[0]


def point_for_ref(ref: tuple) -> dict:
    return point_for(ref[0], f"{ref[1]}{ref[2]}" if len(ref) > 2 and ref[2] else ref[1])


def point_label(p: dict) -> str:
    return f"{p['number']}{p['suffix']}"


def point_roman_label(p: dict) -> str:
    roman = ['I', 'II', 'III', 'IV', 'V', 'VI', 'VII', 'VIII', 'IX', 'X', 'XI', 'XII'][p['number'] - 1]
    return f"{roman}-{p['suffix']}" if p["suffix"] else roman


def point_id(p: dict) -> str:
    return f"atlas.age_{p['age']:02d}.point_{p['number']:02d}{p['suffix'].lower()}"


def assignment_id(p: dict, house: str) -> str:
    return f"{point_id(p)}.{HOUSE_SLUGS[house]}.{slugify(p['assignments'][house])}"


def point_filename(p: dict) -> str:
    coordinate = f"{p['number']:02d}{p['suffix'].lower()}"
    filename_slug = p["filename_slug"] or slugify(p["title"])
    if p["filename_slug"] and not p["suffix"]:
        coordinate = f"{p['number']:02d}"
    if p["filename_slug"] and p["suffix"] == "A":
        coordinate = f"{p['number']:02d}"
    return f"point_{coordinate}_{filename_slug}.md"


def point_path(p: dict) -> str:
    return f"ages/{age_for(p['age'])['slug']}/{point_filename(p)}"


def point_ref(p: dict, prefix="") -> str:
    return f"[{age_for(p['age'])['roman']}:{point_label(p)} — {p['title']}]({prefix}{point_path(p)})"


def source_refs(refs, prefix="") -> str:
    return ", ".join(point_ref(point_for_ref(ref), prefix) for ref in refs)


def assignment_anchor(p: dict, house: str) -> str:
    return f"assignment-age-{p['age']:02d}-point-{p['number']:02d}{p['suffix'].lower()}-{HOUSE_SLUGS[house]}"


def gift_id(house: str, culture: str, gift: str) -> str:
    return f"gift.{HOUSE_SLUGS[house]}.{slugify(culture)}.{slugify(gift)}"


def manifestation_id(house: str, key: str) -> str:
    return f"manifestation.{HOUSE_SLUGS[house]}.{key}"


def manifest_ids_for_assignment(p: dict, house: str) -> list[str]:
    culture = p["assignments"][house]
    coordinate = (p["age"], p["number"])
    return [
        manifestation_id(house, record[0])
        for record in MANIFESTATIONS[house]
        if culture in record[3] and any(
            ref[:2] == coordinate and (len(ref) < 3 or ref[2] == p["suffix"])
            for ref in record[10]
        )
    ]


def dossier_record_for(p: dict, house: str) -> dict | None:
    return REVIEWED_DOSSIERS.get((p["age"], p["number"], p["suffix"]), REVIEWED_DOSSIERS.get((p["age"], p["number"]), {})).get(house)


def dossier_path_for(p: dict, house: str) -> str | None:
    record = dossier_record_for(p, house)
    if not record:
        return None
    return f"dossiers/age_{p['age']:02d}_point_{p['number']:02d}/{record['file']}"


def research_status(p: dict, house: str) -> str:
    culture = p["assignments"][house]
    reviewed = dossier_record_for(p, house)
    if reviewed:
        return reviewed["status"] + "."
    if culture == "Awan":
        return "Needs historical audit; chronology, extent, and House-fit require specialist review."
    if p["age"] == 2 and p["number"] == 6 and house == "Stonebend":
        return "Needs date refinement; Achaemenid is retained as a transitional inheritance after political conquest."
    if culture == "Nazi Germany":
        return "Needs House-fit audit; retained exactly, with only negative/cautionary inheritance permitted."
    temporal_fit = p["assignment_details"][house]["temporal_fit"]
    date_refinement_markers = ("Partial", "Boundary", "Emergent", "Legacy", "Transforming")
    if any(marker in temporal_fit for marker in date_refinement_markers):
        return f"Needs date refinement; temporal fit is classified as {temporal_fit} in Chronology Revision 1."
    if p["age"] in (3, 4):
        return "Needs historical audit; Working post-classical assignment retained or explicitly refined without ratification."
    if p["age"] == 5:
        return "Needs House-fit audit; Working industrial assignment retained or explicitly refined without ratification."
    if p["age"] == 6:
        return "Needs House-fit audit and recurring date review; Working modern assignment is temporally changeable."
    return "Working; supplied ancient/classical assignment preserved, with detailed source research pending."


def manifestations_for_assignment(house: str, gifts: tuple[str, ...]) -> list[str]:
    labels = HOUSE_LENSES[house]["manifest"]
    values = list(gifts[:3])
    while len(values) < 3:
        values.append(values[-1])
    if house == "Stonebend":
        return [
            f"**{labels[0]}:** The inheritance of {values[0]} informs durable, repairable civic form and clearly recorded public works.",
            f"**{labels[1]}:** The inheritance of {values[1]} becomes an academy, standards, or office practice subordinate to Claim / Title / Yield.",
            f"**{labels[2]}:** The inheritance of {values[2]} can tag districts, artifacts, professions, and archive exhibits.",
        ]
    if house == "Sandmanor":
        return [
            f"**{labels[0]}:** The inheritance of {values[0]} informs relational space, ceremony, and public presentation without copied historical costume.",
            f"**{labels[1]}:** The inheritance of {values[1]} becomes a teaching, diplomatic, literary, or design practice bounded by Proof.",
            f"**{labels[2]}:** The inheritance of {values[2]} can tag stories, social roles, exhibits, and cultural-memory encounters.",
        ]
    if house == "Glaüshouse":
        return [
            f"**{labels[0]}:** The inheritance of {values[0]} informs preventive care, restoration, accessible maintenance, or environmental integrity.",
            f"**{labels[1]}:** The inheritance of {values[1]} becomes a clinical, library, translation, ecology, or cognition curriculum.",
            f"**{labels[2]}:** The inheritance of {values[2]} can tag longitudinal records, care spaces, artifacts, and recovery references without creating Clearance.",
        ]
    return [
        f"**{labels[0]}:** The inheritance of {values[0]} informs repairable tools, routes, machine halls, or defensive infrastructure.",
        f"**{labels[1]}:** The inheritance of {values[1]} becomes logistics, engineering, survival, or adversarial-testing training under existing command law.",
        f"**{labels[2]}:** The inheritance of {values[2]} can tag equipment, networks, professions, and after-action records without creating Capacity, command, or confirmation authority.",
    ]


def write(path: Path, content: str) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    normalized = []
    for line in content.rstrip().splitlines():
        if line.endswith("  "):
            line = line[:-2] + "<br>"
        normalized.append(line.rstrip())
    path.write_text("\n".join(normalized) + "\n", encoding="utf-8")


def build_completion_dossier(p: dict, house: str) -> str:
    record = dossier_record_for(p, house)
    culture = p["assignments"][house]
    gifts = gifts_for_assignment(p, house)
    manifestation_ids = manifest_ids_for_assignment(p, house)
    manifestation = manifestation_ids[0]
    sources = COMPLETION_POINT_SOURCES[(p["age"], p["number"])]
    source_lines = "\n".join(
        f"- [Institutional or scholarly source {index}]({url})"
        for index, url in enumerate(sources, start=1)
    )
    gift_lines = "\n".join(
        f"- **{gift}:** retained as an evidence-bounded inheritance category. The label must be tied to a dated source and may not imply that every person, region, or institution in {culture} shared one practice."
        for gift in gifts
    )
    open_boundary = (
        " This is an open, time-sensitive coordinate reviewed through 2026-08-12; later claims require a new dated pass."
        if (p["age"], p["number"]) == (6, 5)
        else ""
    )
    nazi_boundary = (
        " Nazi Germany contributes only documentation of industrialized atrocity, warning against totalitarian law, and institutional refusal. No aesthetic, command method, symbol, prestige, or technical triumph is inherited."
        if culture == "Nazi Germany"
        else ""
    )
    return f"""# {culture} — {age_for(p['age'])['roman']}:{point_label(p)} Completion Dossier

Status: {record['status']}

## Evidence boundary

This is a completion-level dossier for the supplied **{culture}** assignment inside **{p['title']} ({p['date_range']})**. The linked sources establish a Point-level institutional and chronological frame; they do not make this file an exhaustive national, regional, social, or cultural history. Claims must retain date, place, source type, affected communities, and uncertainty. Historical power never transfers authority to a House.{open_boundary}{nazi_boundary}

## Historical overview

{p['summary']} Within that comparison, {culture} remains a distinct and internally varied assignment. Court, state, religious, commercial, scientific, military, industrial, or technical records are not treated as a transparent account of all communities.

## Chronology and temporal fit

- **Atlas range:** {p['date_range']}
- **Temporal fit:** {p['assignment_details'][house]['temporal_fit']}
- **Culture-specific relevance:** {p['assignment_details'][house]['relevance_range']}
- **Boundary note:** {p['assignment_details'][house]['note']}

## Evidence and uncertainty

The review distinguishes primary records and objects, institutional collection interpretation, later scholarship, and Hollow Grove adaptation. It does not infer uniform policy from a capital, universal participation from elite records, or continuity merely because a later institution uses the same name. Empire, colonization, forced labor, exclusion, war, genocide, surveillance, and environmental or civilian cost remain evidence and cautions, never Gifts.

## Permanent Gifts

{gift_lines}

## Modern Hollow Grove manifestation

[`{manifestation}`](../../ANCESTRAL_MANIFESTATIONS_REGISTRY.md#{manifestation}) is a read-only evidence and translation interface. It exposes sources, dates, scope, custody, exclusions, uncertainty, and revision history. It creates no new district, office, jurisdiction, House law, Clearance, Capacity, or gameplay power.

## House interpretation

{house} may translate the reviewed Gifts only through its existing constitution, materials, visual law, library, and cultural-memory practices. Replica costume, flags, sacred objects, dynastic or national authority, military spectacle, and anonymous claims of cultural ownership are excluded.

## Research notes

- Review depth: completion-level source and boundary audit, suitable for Atlas-wide structured coverage.
- Remaining work: culture-specific specialist bibliography, local and non-elite records, disputed terminology, collection custody, and historiographic disagreement may deepen this dossier without reopening Atlas coverage.
- Assignment status: Working. Review improves provenance; it does not canonize the culture-to-House choice.

## Sources

{source_lines}

## Cross-references

- [Point page](../../{point_path(p)})
- [{house} ancestry](../../houses/{HOUSE_FILES[house]})
- [Gifts registry](../../ANCESTRAL_GIFTS_REGISTRY.md)
- [Manifestations registry](../../ANCESTRAL_MANIFESTATIONS_REGISTRY.md)
- [Atlas completion report](../../ATLAS_COMPLETION_REPORT.md)
"""


def build_completion_dossier_readme(p: dict) -> str:
    rows = []
    for house in HOUSES:
        record = dossier_record_for(p, house)
        rows.append(f"| {house} | {record['culture']} | [{record['file']}]({record['file']}) | {record['status']} |")
    return "\n".join([
        f"# Age {age_for(p['age'])['roman']}, Point {point_label(p)} — {p['title']}",
        "",
        f"Range: {p['date_range']}  ",
        "Status: completion-level source review; every Atlas assignment remains Working",
        "",
        "| House | Assignment | Dossier | Review status |",
        "|---|---|---|---|",
        *rows,
        "",
        "These compact dossiers establish evidence boundaries, source provenance, Gifts, and one reviewed manifestation per assignment. They are designed for complete Atlas coverage; culture-specific specialist expansion remains additive work.",
        "",
        f"[Back to Point](../../{point_path(p)}) · [All dossiers](../README.md)",
    ])


def build_dossiers_readme() -> str:
    links = []
    for p in POINTS:
        if not dossier_record_for(p, HOUSES[0]):
            continue
        links.append(
            f"- [Age {age_for(p['age'])['roman']}, Point {point_label(p)} — {p['title']}](age_{p['age']:02d}_point_{p['number']:02d}/README.md)"
        )
    return "\n".join([
        "# Historical Dossiers",
        "",
        "Status: source-reviewed research layer beneath Working Atlas assignments",
        "",
        "Historical dossiers keep historical evidence, scholarly interpretation, and Hollow Grove adaptation separate. A completed dossier makes provenance inspectable; it does not make an assignment Canonical.",
        "",
        f"Coverage: **all {len(POINTS)} operational Points and {len(POINTS) * len(HOUSES)} House assignments**.",
        "",
        "## Reviewed Points",
        "",
        *links,
        "",
        "## Continued refinement",
        "",
        "Use the [Historical Dossier Template](../schemas/HISTORICAL_DOSSIER_TEMPLATE.md) when expanding a completion dossier into a specialist dossier. Expansion must preserve the evidence boundary, Working assignment status, Gift exclusions, manifestation provenance, and cross-references.",
        "",
        "[Back to Atlas Index](../ATLAS_INDEX.md)",
    ])


def relative_canon_links(house: str, depth_prefix: str) -> str:
    return "\n".join(
        f"- [{label}]({depth_prefix}{path})" for label, path in HOUSE_CANON[house]
    )


def atlas_assignment_rows() -> list[dict]:
    records = []
    for p in POINTS:
        for house in HOUSES:
            culture = p["assignments"][house]
            gifts = gifts_for_assignment(p, house)
            record = {
                "id": assignment_id(p, house),
                "age": p["age"],
                "point": p["number"],
                "point_suffix": p["suffix"],
                "point_coordinate": point_label(p),
                "house": HOUSE_SLUGS[house],
                "culture": culture,
                "status": "working",
                "temporal_fit": p["assignment_details"][house]["temporal_fit"],
                "relevance_range": p["assignment_details"][house]["relevance_range"],
                "relevance_note": p["assignment_details"][house]["note"],
                "research_status": research_status(p, house),
                "gifts": [gift_id(house, culture, gift) for gift in gifts],
                "manifestations": manifest_ids_for_assignment(p, house),
                "canon_links": [Path(path).stem.lower() for _, path in HOUSE_CANON[house]],
                "hueman_hooks": ["curriculum", "district_reference", "artifact_provenance", "npc_background"],
                "point_document": point_path(p),
            }
            dossier_document = dossier_path_for(p, house)
            if dossier_document:
                record["dossier_document"] = dossier_document
                record["review_level"] = "reviewed_benchmark" if (p["age"], p["number"]) == (1, 1) else "reviewed_dossier"
            records.append(record)
    return records


def build_point_page(p: dict, previous: dict | None, following: dict | None) -> str:
    age = age_for(p["age"])
    previous_text = (
        "This is the opening coordinate of the supplied Atlas; no previous Point is defined."
        if previous is None
        else f"The Atlas moves from {point_ref(previous, '../../')} into this coordinate; detailed causal claims remain subject to research."
    )
    following_text = (
        "This is the current terminal coordinate; later change remains open and requires recurring review."
        if following is None
        else f"The next working coordinate is {point_ref(following, '../../')}."
    )
    if p["age"] == 2 and p["number"] == 7:
        previous_text = (
            f"The Atlas moves from {point_ref(previous, '../../')} at the 281 successor-generation boundary, not into an already static three-kingdom balance. Antiochus I inherits the Seleucid realm; Ptolemy II continues in Egypt; Greek cities and emerging koina follow distinct political courses; and durable Antigonid rule in Macedonia begins only in 277/276."
        )
        following_text = (
            f"{point_ref(following, '../../')} is a nested western view beginning in 264 inside this Point's latter span, not a sequential replacement. Its Roman–Carthaginian focus helps explain the growth of Roman Mediterranean power that reaches Macedonia in 168 and Corinth in 146, while Ptolemaic and Seleucid states and Greek civic institutions continue beyond the shared Point VII endpoint."
        )
    if p["age"] == 2 and p["number"] == 8:
        previous_text = "This Point is deliberately nested inside Age II, Point VII; it is not a clean chronological succession."
        following_text = f"The western nested view closes in 146 BCE and the Atlas continues with {point_ref(following, '../../')}."
    if p["age"] == 6 and p["number"] == 2:
        previous_text = "This Point is deliberately nested across the closing years of Age VI, Point I; Sputnik opens the technological branch in 1957."
        following_text = f"The nested Space Age coordinate rejoins the main sequence at {point_ref(following, '../../')}."
    if p["age"] == 6 and p["number"] == 1:
        following_text = f"{point_ref(following, '../../')} is a nested technological branch beginning in 1957, within this Point's closing years."
    if p["age"] == 1 and p["number"] == 3:
        previous_text = (
            f"The Atlas moves from {point_ref(previous, '../../')} through four different lineage changes: "
            "post-Akkadian competition precedes Ur III; Old Kingdom fragmentation precedes Egyptian reunification; "
            "Mature Indus and late Prepalatial Crete are parallel House assignments rather than a causal succession; "
            "and the Awan–Šimaški relationship remains poorly resolved."
        )
        following_text = (
            f"Ur III has already ended when {point_ref(following, '../../')} begins. Middle Kingdom Egypt and Minoan Crete "
            "continue under the same supplied labels but enter later internal phases, while the Flynt lineage shifts to Old Assyria; "
            "the Point boundary is therefore a change of comparative coordinate, not one shared collapse or migration."
        )
    if p["age"] == 1 and p["number"] == 4:
        previous_text = (
            f"The Atlas moves from {point_ref(previous, '../../')} after Ur III has ended. Middle Kingdom Egypt continues into a later internal phase; "
            "late Prepalatial Crete crosses into its first court-centered systems; Babylon emerges within the Isin-Larsa successor world; and Old Assyrian merchant evidence supplies a new Flynt lineage rather than a continuation of Šimaški."
        )
        following_text = (
            f"The Point closes unevenly before {point_ref(following, '../../')}: later Middle Kingdom political unity has already fragmented; the richest Old Assyrian merchant record has faded; "
            "Babylon's First Dynasty ends near 1595 BCE; and Cretan Neopalatial systems continue beyond the boundary. Point V therefore begins a new great-power coordinate, not one simultaneous succession event."
        )
    if p["age"] == 1 and p["number"] == 5:
        previous_text = (
            f"The Atlas moves from {point_ref(previous, '../../')} through several unequal transitions: the New Kingdom follows Egypt's Second Intermediate division; Kassite rule emerges after Babylon's First Dynasty through an obscure early phase; "
            "the later Hittite imperial system develops from an older Anatolian kingdom; and Middle Assyrian expansion follows centuries in which Assur was constrained by Mitanni. No single event begins all four assignments."
        )
        following_text = (
            f"The supplied boundary opens {point_ref(following, '../../')} as a post-palatial transition, not a clean replacement of four fallen states. Central rule at Hattusa ends, several eastern Mediterranean palace systems transform, and Egyptian Levantine control contracts, "
            "while New Kingdom Egypt, Kassite Babylonia, Middle Assyria, Carchemish, and many local networks continue on different trajectories beyond 1200 BCE."
        )
    if p["age"] == 2 and p["number"] == 1:
        previous_text = (
            f"The Atlas moves from {point_ref(previous, '../../')} through uneven continuity rather than a universal reset. Egyptian and Assyrian institutions continue beyond 1200; Hittite-successor centers survive; coastal cities retain older populations and exchange; "
            "and new or newly visible highland, mobile, and city-state communities develop within transformed regional systems. The Point therefore records emergence, local recombination, and contraction alongside survival."
        )
        following_text = (
            f"At {point_ref(following, '../../')}, the labels become more securely political but still do not synchronize perfectly: the northern Kingdom of Israel and its external attestations become clearer in the ninth century; Phoenician cities expand their documented networks; Aramaean states and inscriptions become more visible; "
            "and Neo-Assyrian rulers after 900 develop the expansion whose fall of Samaria closes Point II. Point I's settlement, script, and recovery evidence remains a foundation layer rather than being overwritten."
        )
    if p["age"] == 2 and p["number"] == 2:
        previous_text = (
            f"The Atlas moves from {point_ref(previous, '../../')} by changing evidence scale rather than replacing four peoples. Israel becomes the better-attested northern kingdom centered at Samaria; Phoenician ports retain separate identities while their settlement networks grow; locally distinct Aramaean polities and inscriptions become more visible; and Neo-Assyria enters a long expansion marked by internal interruption as well as conquest."
        )
        following_text = (
            f"The supplied fall of Samaria closes the Israel assignment before {point_ref(following, '../../')}, though the conquest, deportation, provincial reorganization, and Sargon II succession evidence crosses the 722/721 boundary. Phoenician cities, Aramaic language communities, and Assyria continue on unequal trajectories; Point III changes all four House assignments and must not imply that the underlying populations or networks disappeared."
        )
    if p["age"] == 2 and p["number"] == 3:
        previous_text = (
            f"The Atlas moves from {point_ref(previous, '../../')} after the northern Kingdom of Israel falls, but not after the regional interaction system disappears. Judah receives migrants and grows under Assyrian dominance; Kushite Egypt becomes a direct imperial rival; Babylon remains a contested kingship and scholarly center; and Sargon II begins the Sargonid phase of Neo-Assyria."
        )
        following_text = (
            f"The fall of Nineveh closes this supplied Point before {point_ref(following, '../../')}, but the transition is staggered. Assyrian resistance continues from Harran until 609; Nabopolassar's Babylonian dynasty, Judah, and Saite Egypt cross the 612 boundary; and Point IV's new assignments must distinguish capital destruction, polity end, and continuing communities."
        )
    if p["age"] == 2 and p["number"] == 4:
        previous_text = (
            f"The Atlas moves from {point_ref(previous, '../../')} through staggered survival and succession. Assyrian resistance continues to 609 after Nineveh; Nabopolassar's dynasty already rules Babylon; Judah and Saite Egypt cross 612 as continuing states; and Median coalition power is visible in Assyria's destruction. The boundary changes the comparative center rather than beginning four new societies."
        )
        following_text = (
            f"Cyrus's capture of Babylon opens {point_ref(following, '../../')} as an Achaemenid-centered coordinate, but the handoff remains uneven. Babylonian urban, temple, archival, and scholarly institutions continue; Median people and elites remain within Persian systems after Astyages's earlier defeat; Judahite communities do not all return at once; and Saite Egypt remains independent until 525. The Greek, Late Egypt, and Macedonia assignments are parallel comparison choices, not direct replacements created in 539."
        )
    if p["age"] == 2 and p["number"] == 5:
        previous_text = (
            f"Cyrus's capture of Babylon closes {point_ref(previous, '../../')} and opens this Achaemenid-centered coordinate without erasing Babylonian institutions, Median people, or distributed Judahite communities. Saite Egypt remains independent until 525; Greek communities and Macedonia do not begin in 539 and enter the comparison through their own longer histories."
        )
        following_text = (
            f"Philip II's death and Alexander III's accession in 336 open {point_ref(following, '../../')}, but Achaemenid kingship continues under Darius III until 330 and Late Egyptian second Persian rule continues until 332. Macedonia changes from a late-dominant Flynt comparison into Point VI's conquest-centered Sandmanor assignment, while Ptolemaic and Seleucid states emerge only after Alexander's death; the handoff is therefore phased rather than instantaneous."
        )
    if p["age"] == 2 and p["number"] == 6:
        previous_text = (
            f"The Atlas moves from {point_ref(previous, '../../')} at Alexander III's accession in 336. Achaemenid government and Darius III remain political realities until 330, Macedonia enters a conquest and successor phase, Egypt remains under Achaemenid rule until 332, and Ptolemaic and Seleucid assignments emerge only later within this coordinate."
        )
        following_text = (
            f"Corupedium in 281 and the deaths of Lysimachus and Seleucus I close this first successor-generation formation arc before {point_ref(following, '../../')}, but they do not produce an instantaneous stable system. Ptolemaic and Seleucid states continue under dynastic succession; Greek cities and leagues retain distinct political lives; and Antigonid rule in Macedonia becomes durable only after further conflict. Point VII is therefore a mature-system comparison, not a claim that successor war ended everywhere in 281."
        )

    nav = []
    if previous:
        nav.append(f"[← {previous['title']}](../../{point_path(previous)})")
    nav.append("[Age index](README.md)")
    nav.append("[Atlas index](../../ATLAS_INDEX.md)")
    if following:
        nav.append(f"[{following['title']} →](../../{point_path(following)})")

    lines = [
        f"# Age {age['roman']} / Point {point_label(p)} — {p['title']}",
        "",
        "Status: Working  ",
        f"Atlas ID: `{point_id(p)}`  ",
        f"Age: {age['title']}  ",
        f"Point number: {point_label(p)}  ",
        f"Point title: {p['title']}  ",
        f"Date range: {p['date_range']}  ",
        f"Point type: {p['point_type'].title()}  ",
        f"Boundary rationale: {p['boundary_rationale']}",
        "",
        " | ".join(nav),
        "",
        "## Historical summary",
        "",
        p["summary"],
        "",
        "## Reason this Point exists",
        "",
        f"This Point carries the approved four-House coordinate for **{p['title']}** and adds a reviewable inheritance layer without making any source culture a literal predecessor state of Hollow Grove. Any departure from the supplied baseline is recorded in [Chronology Revision 1](../../CHRONOLOGY_REVISION_01_REPORT.md).",
        "",
        "## Transition from previous Point",
        "",
        previous_text,
        "",
        "## Transition into next Point",
        "",
        following_text,
    ]
    if p["as_of"]:
        lines.extend([
            "",
            "## Open-Point review",
            "",
            f"As of: {p['as_of']}  ",
            f"Review due: {p['review_due']}  ",
            "This open Point must be re-evaluated when its review date arrives or a major historical change materially alters its assignments.",
        ])
    if p["note"]:
        lines.extend(["", "## Supplied transition note", "", p["note"]])
    lines.extend([
        "",
        "## Four-House coordinate",
        "",
        "| House | Primary culture | House lineage |",
        "|---|---|---|",
    ])
    for house in HOUSES:
        lines.append(
            f"| {house} | {p['assignments'][house]} | "
            f"[{house} ancestry](../../houses/{HOUSE_FILES[house]}) |"
        )

    for house in HOUSES:
        culture = p["assignments"][house]
        gifts = gifts_for_assignment(p, house)
        reviewed = dossier_record_for(p, house)
        assignment_detail = p["assignment_details"][house]
        if reviewed:
            dossier_link = f"../../{dossier_path_for(p, house)}"
            historical_role = f"Reviewed inheritance lens for {', '.join(gifts)}; see the linked dossier for evidence, interpretation, and adaptation boundaries."
            major_figures = reviewed["figures"]
            major_locations = reviewed["locations"]
            major_records = reviewed["records"]
            government = reviewed["government"]
            worldview = reviewed["worldview"]
            knowledge = reviewed["knowledge"]
            technology = reviewed["technology"]
            art = reviewed["art"]
            warfare = reviewed["warfare"]
            trade = reviewed["trade"]
            relationships = reviewed["relationships"]
        else:
            dossier_link = None
            historical_role = f"Working inheritance lens for {', '.join(gifts)}; this is not a total description of {culture}."
            major_figures = "Research pending; no figure is locked by this preliminary assignment."
            major_locations = "Research pending; no literal replica district is authorized."
            major_records = "Research pending; see the House library for current foundational works."
            government = "Research pending; preliminary institutional inheritance is expressed only through the Gifts below."
            worldview = "Research pending; no doctrine is imported into Hollow Grove canon."
            knowledge = "Research pending; the preliminary knowledge inheritance is limited to the concrete Gifts below."
            technology = "Research pending; preliminary translation appears under modern manifestation."
            art = "Research pending; visual use must pass through Hollow Grove's established visual canon."
            warfare = "Research pending; no unsupported conflict or command relationship is asserted."
            trade = "Research pending; trade claims require source review."
            relationships = "Research pending; Point co-placement alone does not prove direct contact."
        lines.extend([
            "",
            f'<a id="{assignment_anchor(p, house)}"></a>',
            f"## {house} — {culture}",
            "",
            f"**House:** [{house}](../../houses/{HOUSE_FILES[house]})  ",
            f"**Assignment ID:** `{assignment_id(p, house)}`  ",
            f"**Primary culture:** {culture}  ",
            f"**Temporal fit:** {assignment_detail['temporal_fit']}  ",
            f"**Date relevance:** {assignment_detail['relevance_range']}. {assignment_detail['note']}  ",
            f"**Historical role:** {historical_role}  ",
            f"**Major figures:** {major_figures}  ",
            f"**Major locations:** {major_locations}  ",
            f"**Major works or records:** {major_records}  ",
            f"**Government and institutions:** {government}  ",
            f"**Religion and worldview:** {worldview}  ",
            f"**Science and knowledge:** {knowledge}  ",
            f"**Technology and infrastructure:** {technology}  ",
            f"**Art and cultural expression:** {art}  ",
            f"**Warfare and strategic capacity:** {warfare}  ",
            f"**Resources and trade:** {trade}  ",
            f"**Major conflicts and relationships:** {relationships}  ",
            "",
            "### Permanent gifts",
            "",
        ])
        for gift in gifts:
            lines.append(f"- `{gift_id(house, culture, gift)}` — {gift}")
        lines.extend(["", "### Modern Hollow Grove manifestation", ""])
        lines.extend(f"- {item}" for item in manifestations_for_assignment(house, gifts))
        lines.extend([
            "",
            "### Related existing Hollow Grove canon",
            "",
            relative_canon_links(house, "../../../../../"),
            "",
            "The ancestry may deepen these systems but grants no office, law, proof, clearance, recognition, consent, or runtime behavior.",
            "",
            "### Implementation opportunities",
            "",
            f"- Use `{assignment_id(p, house)}` as a read-only curriculum, district, artifact, NPC-background, or exhibit reference.",
            f"- Filter the [Gifts registry](../../ANCESTRAL_GIFTS_REGISTRY.md) by `{HOUSE_SLUGS[house]}` and this Point.",
        ])
        if dossier_link:
            lines.append(f"- Use the reviewed [{culture} historical dossier]({dossier_link}) as the evidence boundary for new design claims.")
        mids = manifest_ids_for_assignment(p, house)
        if mids:
            lines.append("- High-confidence registry hooks: " + ", ".join(f"`{mid}`" for mid in mids) + ".")
        else:
            lines.append("- No high-confidence shared manifestation is registered yet; the preliminary Point translation remains available for later review.")
        lines.extend([
            "",
            "### Source or research status",
            "",
            f"**{research_status(p, house)}** " + (f"Reviewed source dossier: [{culture}]({dossier_link})." if dossier_link else "No external source dossier has yet been attached to this assignment."),
        ])
    lines.extend([
        "",
        "## Ancestral provenance block",
        "",
        "```text",
        "Ancestral provenance:",
    ])
    for house in HOUSES:
        lines.append(f"- Age {age['roman']}, Point {point_label(p)}, {house} — {p['assignments'][house]}")
    lines.extend([
        "",
        "Derived Gifts:",
        "- select only from the assignment records above",
        "",
        "Modern manifestation:",
        "- record a manifestation ID or mark the proposal Working",
        "```",
    ])
    return "\n".join(lines)


def build_master_timeline() -> str:
    lines = [
        "# The Ancestral Atlas",
        "",
        "## Chronological House Assignment — Working Version 1",
        "",
        "Status: Working Version 1 with approved Chronology Revision 1  ",
        "Authority: descriptive ancestry beneath the Hollow Grove Compromise and House constitutions",
        "",
        "> This document preserves the supplied House-assignment skeleton while applying the explicitly approved Chronology Revision 1. The supplied forms changed by that revision remain recorded in the [revision report](CHRONOLOGY_REVISION_01_REPORT.md); legacy master lineages below remain verbatim. Navigable Point pages are the operational Working source.",
    ]
    for age in AGES:
        lines.extend([
            "",
            f"# AGE {age['roman']} — {age['title'].upper()}",
            "",
            f"## {age['range']}",
        ])
        for p in [item for item in POINTS if item["age"] == age["number"]]:
            lines.extend([
                "",
                f"## Point {point_roman_label(p)} — {p['title']}",
                "",
                f"### {p['date_range']}",
            ])
            if p["point_type"] != "sequential":
                lines.extend(["", f"### Point type: {p['point_type'].title()}"])
            if p["age"] == 2 and p["number"] == 8:
                lines.extend(["", "### Nested western Point overlapping Point VII"])
            lines.append("")
            for house in HOUSES:
                lines.append(f"* **{house} — {p['assignments'][house]}**")
            if p["note"]:
                note = p["note"].replace("**Nested western Point overlapping Point VII**\n\n", "")
                if note:
                    lines.extend(["", note])
    lines.extend(["", "# MASTER HOUSE LINEAGES", ""])
    for house in HOUSES:
        lines.extend([f"## {house}", ""])
        for index, culture in enumerate(LEGACY_LINEAGES[house]):
            if index == 0:
                lines.append(culture)
            else:
                lines.append(f"→ {culture}")
        lines.extend(["", "---", ""])
    lines.extend([
        "# STATUS",
        "",
        "This document establishes the **chronological and cultural assignment skeleton** of the Ancestral Atlas.",
        "",
        "Points are representative coordinates, not necessarily continuous chronological bins. Culture-specific relevance ranges, transition Points, nested Points, and open Points preserve uneven historical timing without forcing false synchrony.",
        "",
        "It does not yet permanently lock every post-medieval assignment. Ages I and II contain the most developed historical work. Ages III through VI remain working assignments that can be refined while preserving the Age → Point → House structure.",
    ])
    return "\n".join(lines)


def build_atlas_index() -> str:
    lines = [
        "# Ancestral Atlas Index",
        "",
        "Status: canonical navigation for a Working assignment set",
        "",
        "Use [chronological navigation](#chronological-navigation) to ask what the four ancestries were at a Point, or the [House lineages](#house-lineage-navigation) to ask how one House accumulated its present culture.",
        "",
        "## Chronological navigation",
        "",
    ]
    for age in AGES:
        lines.extend([
            f"### Age {age['roman']} — [{age['title']}](ages/{age['slug']}/README.md)",
            "",
            "| Point | Type | Date range | Stonebend | Sandmanor | Glaüshouse | Flynt |",
            "|---|---|---|---|---|---|---|",
        ])
        for p in [item for item in POINTS if item["age"] == age["number"]]:
            link = point_path(p)
            lines.append(
                f"| [{point_label(p)}. {p['title']}]({link}) | {p['point_type'].title()} | {p['date_range']} | "
                + " | ".join(p["assignments"][house] for house in HOUSES)
                + " |"
            )
        lines.append("")
    lines.extend([
        "## House-lineage navigation",
        "",
    ])
    for house in HOUSES:
        lines.append(f"- [{house} ancestry](houses/{HOUSE_FILES[house]}) → [cultural synthesis](houses/{HOUSE_SLUGS[house].upper()}_ANCESTRAL_SYNTHESIS.md)")
    lines.extend([
        "",
        "## Integration registries",
        "",
        "- [Permanent Gifts](ANCESTRAL_GIFTS_REGISTRY.md)",
        "- [High-confidence manifestations](ANCESTRAL_MANIFESTATIONS_REGISTRY.md)",
        "- [Historical dossiers](dossiers/README.md)",
        "- [Cultural memory model](CULTURAL_MEMORY_MODEL.md)",
        "- [House libraries](libraries/README.md)",
        "- [Hueman metadata proposal](HUEMAN_METADATA_PROPOSAL.md)",
        "- [How to use the Atlas](HOW_TO_USE_THE_ANCESTRAL_ATLAS.md)",
        "- [Chronology Revision 1](CHRONOLOGY_REVISION_01_REPORT.md)",
        "- [Audit report](AUDIT_REPORT.md)",
        "- [Integration report](INTEGRATION_REPORT.md)",
    ])
    return "\n".join(lines)


