def build_gifts_registry() -> str:
    lines = [
        "# Ancestral Gifts Registry",
        "",
        f"Status: Working registry; complete preliminary coverage for all {len(POINTS)} operational Points and {len(POINTS) * len(HOUSES)} assignments",
        "",
        "A Gift is a concrete historical inheritance carried into a House design vocabulary. Gifts can include preserved cautions and failure knowledge; the term never implies moral endorsement of a source regime. Repeated culture/Gift combinations are one record with every source Point listed.",
        "",
        f"Registry totals: **{len(gift_records())} unique House-culture Gift records** across **{len(POINTS) * len(HOUSES)} assignments**.",
    ]
    current_house = None
    for record in gift_records():
        house = record["house"]
        if house != current_house:
            lines.extend(["", f"# {house} Gifts"])
            current_house = house
        source_links = []
        for source in record["sources"]:
            source_links.append(
                f"[Age {source['age']}, Point {source['point_coordinate']} — {source['point_title']}]({source['document']}#{source['anchor']})"
            )
        reviewed_gift = REVIEWED_GIFT_REVIEWS.get(record["name"])
        if reviewed_gift:
            historical_meaning, modern_expression = reviewed_gift
            first_source = record["sources"][0]
            dossier = dossier_path_for(
                point_for(first_source["age"], first_source["point_coordinate"]),
                record["house"],
            )
        else:
            historical_meaning = f"Preliminary design term extracted from the supplied {record['culture']} assignment; detailed historical scope requires cited research."
            modern_expression = manifestations_for_assignment(house, (record["name"], record["name"], record["name"]))[0].replace("**", "")
            dossier = None
        lines.extend([
            "",
            f'<a id="{record["id"]}"></a>',
            f"## {record['id']}",
            "",
            f"**Gift ID:** `{record['id']}`  ",
            f"**Gift name:** {record['name']}  ",
            f"**Source culture:** {record['culture']}  ",
            f"**Age:** {', '.join(str(s['age']) for s in record['sources'])}  ",
            f"**Point:** {', '.join(s['point_coordinate'] for s in record['sources'])}  ",
            f"**Primary House:** [{house}](houses/{HOUSE_FILES[house]})  ",
            f"**Historical meaning:** {historical_meaning}  ",
            f"**Modern House expression:** {modern_expression}  ",
            f"**Existing canon connection:** {HOUSE_LENSES[house]['canon']}; ancestry creates no authority.  ",
            f"**Possible Hueman use:** curriculum tag, artifact provenance, district reference, NPC profession or museum filter.  ",
            f"**Status:** {record['status']}  ",
            f"**Source Points:** {'; '.join(source_links)}",
        ])
        if dossier:
            lines.append(f"**Reviewed dossier:** [{record['culture']}]({dossier})")
    return "\n".join(lines)


def build_manifestations_registry() -> str:
    lines = [
        "# Ancestral Manifestations Registry",
        "",
        "Status: Working, limited high-confidence first set",
        "",
        "These manifestations translate several Gifts into modern Hollow Grove design. They are proposals and references, not newly established offices, districts, gameplay systems, or permissions. Historical form must pass through the existing geography, materials, palettes, technology, and constitutional authority.",
        "",
        "| House | Count |",
        "|---|---:|",
    ]
    for house in HOUSES:
        lines.append(f"| {house} | {len(MANIFESTATIONS[house])} |")
    for house in HOUSES:
        lines.extend(["", f"# {house}"])
        for record in MANIFESTATIONS[house]:
            key, name, gifts, cultures, category, description, connection, institution, npc, hook, refs = record
            mid = manifestation_id(house, key)
            reviewed = REVIEWED_MANIFESTATIONS.get(mid)
            source_gift_ids = []
            for culture, gift in zip(cultures, gifts):
                source_gift_ids.append(gift_id(house, culture, gift))
            # If a manifestation combines more Gifts than cultures or vice versa,
            # retain readable names while validation reports unresolved mappings.
            lines.extend(["", f'<a id="{mid}"></a>', f"## {name}", "", f"**Manifestation ID:** `{mid}`  "])
            if reviewed:
                source_list = "; ".join(f"[Scholarly or collection source {index}]({url})" for index, url in enumerate(reviewed["sources"], start=1))
                reviewed_dossier = dossier_path_for(point_for_ref(refs[0]), house)
                lines.extend([
                    f"**Manifestation:** {name}  ",
                    f"**Primary House:** [{house}](houses/{HOUSE_FILES[house]})  ",
                    f"**Purpose:** {reviewed['purpose']}  ",
                    f"**Historical ancestry:** {reviewed['ancestry']} See the [{cultures[0]} dossier]({reviewed_dossier}).  ",
                    "**Source Gifts:** " + ", ".join(f"[`{gid}`](ANCESTRAL_GIFTS_REGISTRY.md#{gid})" for gid in source_gift_ids) + "  ",
                    f"**Modern House interpretation:** {reviewed['interpretation']}  ",
                    f"**Physical appearance:** {reviewed['appearance']}  ",
                    f"**Institutional role:** {reviewed['institutional_role']}  ",
                    f"**Gameplay potential:** {reviewed['gameplay']}  ",
                    f"**Implementation notes:** {reviewed['implementation']}  ",
                    f"**Current canon connection:** {HOUSE_LENSES[house]['canon']}; see [{house} canon links](houses/{HOUSE_FILES[house]}#existing-canon-bridge).  ",
                    f"**Possible NPC role:** {npc}  ",
                    f"**Possible Hueman data hook:** {hook}  ",
                    f"**Confidence:** {reviewed['confidence']}  ",
                    f"**Sources:** {source_list}  ",
                    "**Status:** Reviewed flagship; design remains Working until separately adopted  ",
                    f"**Ancestral provenance:** {source_refs(refs)}",
                ])
            else:
                lines.extend([
                    f"**Name:** {name}  ",
                    f"**Primary House:** [{house}](houses/{HOUSE_FILES[house]})  ",
                    "**Source Gifts:** " + ", ".join(f"[`{gid}`](ANCESTRAL_GIFTS_REGISTRY.md#{gid})" for gid in source_gift_ids) + "  ",
                    f"**Source cultures:** {', '.join(dict.fromkeys(cultures))}  ",
                    f"**Manifestation category:** {category}  ",
                    f"**Description:** {description}  ",
                    f"**Current canon connection:** {HOUSE_LENSES[house]['canon']}; placement cue: {connection}; see [{house} canon links](houses/{HOUSE_FILES[house]}#existing-canon-bridge).  ",
                    f"**Possible physical location:** Working {house} placement associated with {connection}; exact siting requires geography review.  ",
                    f"**Possible institution:** {institution}  ",
                    f"**Possible NPC role:** {npc}  ",
                    f"**Possible Hueman data hook:** {hook}  ",
                    "**Status:** Working  ",
                    f"**Ancestral provenance:** {source_refs(refs)}",
                ])
    return "\n".join(lines)


