def assigned_house_for_culture(p: dict, culture: str) -> str | None:
    for house, assigned in p["assignments"].items():
        if assigned == culture:
            return house
    return None


def build_library(house: str) -> str:
    info = LIBRARY_INFO[house]
    slug = HOUSE_SLUGS[house].upper()
    point_one = point_for(1, 1)
    point_one_culture = POINT_I_DOSSIERS[house]["culture"]
    point_one_manifest = manifest_ids_for_assignment(point_one, house)[0]
    point_two = point_for(1, 2)
    point_two_culture = POINT_II_DOSSIERS[house]["culture"]
    point_two_manifest = manifest_ids_for_assignment(point_two, house)[0]
    point_three = point_for(1, 3)
    point_three_culture = POINT_III_DOSSIERS[house]["culture"]
    point_three_manifest = manifest_ids_for_assignment(point_three, house)[0]
    point_four = point_for(1, 4)
    point_four_culture = POINT_IV_DOSSIERS[house]["culture"]
    point_four_manifest = manifest_ids_for_assignment(point_four, house)[0]
    point_five = point_for(1, 5)
    point_five_culture = POINT_V_DOSSIERS[house]["culture"]
