def data_document() -> dict:
    assignments = atlas_assignment_rows()
    ages = []
    for age in AGES:
        age_points = []
        for p in [item for item in POINTS if item["age"] == age["number"]]:
            age_points.append({
                "id": point_id(p),
                "number": p["number"],
                "suffix": p["suffix"],
                "coordinate": point_label(p),
                "title": p["title"],
                "date_range": p["date_range"],
                "point_type": p["point_type"],
                "boundary_rationale": p["boundary_rationale"],
                "status": "working",
                "document": point_path(p),
                "assignment_ids": [assignment_id(p, house) for house in HOUSES],
            })
            if p["as_of"]:
                age_points[-1]["as_of"] = p["as_of"]
                age_points[-1]["review_due"] = p["review_due"]
        ages.append({
            "id": f"atlas.age_{age['number']:02d}",
            "number": age["number"],
            "title": age["title"],
            "date_range": age["range"],
            "status": "working",
            "points": age_points,
        })
    manifestations = []
    for house in HOUSES:
        for record in MANIFESTATIONS[house]:
            key, name, gifts, cultures, category, description, connection, institution, npc, hook, refs = record
            mid = manifestation_id(house, key)
            manifest_record = {
                "id": mid,
                "name": name,
                "house": HOUSE_SLUGS[house],
                "source_gifts": [gift_id(house, culture, gift) for culture, gift in zip(cultures, gifts)],
                "source_cultures": list(dict.fromkeys(cultures)),
                "category": category,
                "description": description,
                "canon_connection": f"{HOUSE_LENSES[house]['canon']}; placement cue: {connection}",
                "possible_location": f"Working {house} placement associated with {connection}; exact siting requires geography review.",
                "possible_institution": institution,
                "possible_npc_role": npc,
                "hueman_hook": hook,
                "status": "working",
                "provenance": [
                    {
                        "age": age,
                        "point": point_for_ref(ref)["number"],
                        "point_suffix": point_for_ref(ref)["suffix"],
                        "point_coordinate": point_label(point_for_ref(ref)),
                    }
                    for ref in refs
                    for age, point_no in [(ref[0], ref[1])]
                ],
            }
            reviewed = REVIEWED_MANIFESTATIONS.get(mid)
            if reviewed:
                manifest_record.update({
                    "review_level": "reviewed_flagship",
                    "purpose": reviewed["purpose"],
                    "historical_ancestry": reviewed["ancestry"],
                    "modern_house_interpretation": reviewed["interpretation"],
                    "physical_appearance": reviewed["appearance"],
                    "institutional_role": reviewed["institutional_role"],
                    "gameplay_potential": reviewed["gameplay"],
                    "implementation_notes": reviewed["implementation"],
                    "confidence": reviewed["confidence"],
                    "sources": reviewed["sources"],
                    "dossier_document": dossier_path_for(point_for_ref(refs[0]), house),
                })
            manifestations.append(manifest_record)
    books = []
    for house in HOUSES:
        for index, book in enumerate(BOOKS[house], start=1):
            author, title, date, age_no, point_no, culture, relationship, reason = book
            status = "working"
            if "needs verification" in relationship or "Not a single" in relationship or title == "Man and His Symbols":
                status = "needs_title_verification"
            elif "not a supplied primary" in relationship or "not a supplied" in relationship:
                status = "needs_house_fit_audit"
            books.append({
                "id": f"book.{HOUSE_SLUGS[house]}.{index:02d}.{slugify(title)}",
                "title": title,
                "author": author,
                "date_or_period": date,
                "primary_house": HOUSE_SLUGS[house],
                "associated_age": age_no,
                "associated_point": point_no,
                "associated_culture": culture,
                "relationship": relationship,
                "reason": reason,
                "status": status,
            })
    return {
        "version": "working-v1",
        "framework_status": "canonical_descriptive_layer",
        "assignment_status": "working",
        "authority": "Beneath the Hollow Grove Compromise and House constitutions; read-only descriptive context.",
        "ages": ages,
        "assignments": assignments,
        "gifts": gift_records(),
        "manifestations": manifestations,
        "books": books,
    }


